WHERE LOWER(client_email) LIKE '%test%' OR LOWER(vessel_name) LIKE '%test%';

-- inspections com test
SELECT 'inspections' as tabela, COUNT(*) FROM inspections 
WHERE LOWER(vessel_name) LIKE '%test%' OR LOWER(notes) LIKE '%test%';

-- fuel_records com test
