WHERE LOWER(description) LIKE '%test%';

-- maintenances com test
SELECT 'maintenances' as tabela, COUNT(*) FROM maintenances 
WHERE LOWER(description) LIKE '%test%' OR LOWER(vessel_name) LIKE '%test%';

